from __future__ import annotations
import json, re, sys, types
from decimal import Decimal

def install_stubs():
    psycopg2=types.ModuleType("psycopg2")
    psycopg2.connect=lambda **kwargs: None
    sys.modules["psycopg2"]=psycopg2
    google=sys.modules.get("google") or types.ModuleType("google")
    if not hasattr(google,"__path__"): google.__path__=[]
    cloud=types.ModuleType("google.cloud"); cloud.__path__=[]
    tasks=types.ModuleType("google.cloud.tasks_v2")
    class CloudTasksClient: pass
    tasks.CloudTasksClient=CloudTasksClient
    cloud.tasks_v2=tasks; google.cloud=cloud
    sys.modules["google"]=google
    sys.modules["google.cloud"]=cloud
    sys.modules["google.cloud.tasks_v2"]=tasks

def norm(value):
    if isinstance(value, Decimal):
        return {"kind":"Decimal","value":str(value)}
    if isinstance(value, re.Pattern):
        return {"kind":"Pattern","pattern":value.pattern,"flags":value.flags}
    if isinstance(value, set):
        items=[norm(x) for x in value]
        return {"kind":"set","items":sorted(items, key=lambda x: json.dumps(x,sort_keys=True,default=str))}
    if isinstance(value, tuple):
        return {"kind":"tuple","items":[norm(x) for x in value]}
    if isinstance(value, list):
        return [norm(x) for x in value]
    if isinstance(value, dict):
        return {str(k):norm(v) for k,v in sorted(value.items(),key=lambda kv:str(kv[0]))}
    if isinstance(value, (str,int,float,bool)) or value is None:
        return value
    return {"kind":type(value).__name__,"repr":repr(value)}

